import {createAdminClientsUI} from './admin-clients-ui.js';
import {createInternalMarketingUI} from './internal-marketing-ui.js';
import {createManualWhatsAppUI} from './whatsapp-manual-ui.js';
import {createTemplateCatalogUI} from './template-catalog-ui.js';
import {createAIManagementUI} from './ai-management-ui.js';
import {createCommerceUI} from './commerce-ui.js';
import {createFinanceUI} from './finance-ui.js';
import {createAssistedUI} from './assisted-ui.js';
import {createConsultationUI} from './consultation-ui.js';
import {createCommercialUI} from './commercial-ui.js';
import {createPricingUI} from './pricing-ui.js';
import {uploadFile} from './upload.js';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const routes=[['home','Visão geral'],['clients','Clientes'],['marketing','Criação da Helpu'],['whatsapp','Atendimento WhatsApp'],['templates','Biblioteca de templates'],['finance','Financeiro'],['commerce','Planos e produção'],['intelligence','Inteligência e consumo'],['admin','Publicações'],['consultations-admin','Consultorias e sites'],['commercial','Comercial'],['pricing','Planos e custos']];
let boot,S,view='home',ticket=0,timer,denied=false;
async function api(url,method='GET',data){const r=await fetch(url,{method,credentials:'same-origin',headers:data===undefined?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});if(r.status===401){location.replace('entrar.html');throw new Error('Entre para continuar.');}const result=await r.json();if(r.status===403&&!boot?.operator){deny();throw new Error('Acesso restrito à equipe autorizada.');}if(!r.ok)throw new Error(result.error||'Não foi possível carregar. Tente novamente.');return result;}
function deny(){denied=true;boot=null;++ticket;$('#editor').close();$('#admin-shell').hidden=true;$('#admin-gate').hidden=false;$('#admin-gate').innerHTML='<h1>Acesso restrito à equipe Helpu</h1><p>Esta conta não tem autorização administrativa.</p><a class="p-button primary" href="portal.html?mode=client">Abrir meu portal</a>';}
function toast(message,error=false){clearTimeout(timer);const el=$('#toast');el.textContent=message;el.className='toast'+(error?' error':'');el.hidden=false;timer=setTimeout(()=>el.hidden=true,6500);}
function openDialog(title,body,wide=false){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=body;$('#editor').classList.toggle('wide',wide);if(!$('#editor').open)$('#editor').showModal();$('#editor').scrollTop=0;}
function closeDialog(){$('#editor').close();$('#dialog-body').innerHTML='';}
const shared={api,esc,getState:()=>S,getBoot:()=>boot,openDialog,closeDialog,toast,uploadFile};
const whatsapp=createManualWhatsAppUI(shared),templates=createTemplateCatalogUI(shared),assisted=createAssistedUI(shared),consultation=createConsultationUI(shared),commercial=createCommercialUI(shared),pricing=createPricingUI(shared),finance=createFinanceUI(shared),commerce=createCommerceUI(shared),intelligence=createAIManagementUI(shared),clientsUI=createAdminClientsUI(shared),marketingUI=createInternalMarketingUI(shared),modules=[clientsUI,marketingUI,whatsapp,templates,assisted,consultation,commercial,pricing,finance,commerce,intelligence];
const heading=(title,subtitle)=>`<section class="page-heading"><div><p class="overline">ADMINISTRAÇÃO HELPU</p><h1>${title}</h1><p>${subtitle}</p></div></section>`;
function home(d){const t=d.totals;return heading('Sua operação, em um só lugar.','Acompanhe o que chegou, o que precisa de atenção e o próximo passo da equipe.')+`<div class="admin-kpis">${[['clients','Empresas cadastradas',t.clients],['admin','Publicações em aberto',t.publications],['consultations-admin','Consultorias em andamento',t.consultations],['commercial','Novos interesses',t.newInterests]].map(([id,label,n])=>`<a href="#/${id}"><span>${label}</span><strong>${n}</strong><span>Abrir área ↗</span></a>`).join('')}</div><div class="admin-columns"><section class="admin-box"><h2>Próximos passos</h2><a class="admin-task" href="#/admin"><strong>Revisar pedidos de publicação</strong><span>${t.publications} pedido(s) em aberto, incluindo aprovações e ajustes.</span></a><a class="admin-task" href="#/consultations-admin"><strong>Conduzir consultorias</strong><span>${t.consultations} pedido(s) em andamento, da triagem à entrega.</span></a><a class="admin-task" href="#/commercial"><strong>Acompanhar propostas</strong><span>${t.proposals} proposta(s) enviada(s), ainda sem aceite registrado. Confira a validade ao abrir.</span></a><a class="admin-task" href="#/clients"><strong>Conferir clientes com falhas registradas</strong><span>${t.failedJobs} execução(ões) com falha no histórico. O total não confirma incidentes atuais.</span></a></section><section class="admin-box"><h2>Organize a oferta</h2><p>Prepare suas apresentações, acompanhe os interessados e defina cada proposta com entregas e condições claras.</p><a class="p-button primary" href="#/commercial">Abrir comercial</a><a class="admin-task" href="#/pricing"><strong>Planos, custos e capacidade ↗</strong><span>Compare cenários antes de escolher os preços.</span></a><aside class="admin-callout"><strong>Financeiro e pagamentos</strong><p>Cadastre cobranças com Pix ou boleto e confira os recebimentos no banco. <a href="#/finance">Abrir financeiro ↗</a></p></aside></section></div>`;}
async function render(){if(!boot?.operator||!S)return;const current=++ticket;closeDialog();view=location.hash.replace(/^#\//,'').split('?')[0]||'home';if(!routes.some(([id])=>id===view))view='home';document.title=routes.find(([id])=>id===view)[1]+' — Administração Helpu';$('#admin-nav').innerHTML=routes.map(([id,name],i)=>`<a href="#/${id}" ${id===view?'aria-current="page"':''}><span aria-hidden="true">${String(i+1).padStart(2,'0')}</span>${name}</a>`).join('');$('#admin-origin').hidden=!['pricing','commercial','templates'].includes(view);for(const m of modules)m.mount('');const screens={clients:()=>clientsUI.page(),marketing:()=>marketingUI.page(),whatsapp:()=>whatsapp.page(),templates:()=>templates.page(true),intelligence:()=>intelligence.page(),commerce:()=>commerce.page(true),finance:()=>finance.page(true),admin:()=>assisted.page(true),'consultations-admin':()=>consultation.page(true),commercial:()=>commercial.page(true),pricing:()=>pricing.page()};$('#workspace').innerHTML=screens[view]?screens[view]():'<p role="status">Carregando a operação…</p>';for(const m of modules)m.mount(view);if(view==='home'){try{const d=await api('/api/portal/admin-overview');if(current!==ticket||!boot)return;$('#workspace').innerHTML=home(d);}catch(e){if(current===ticket&&boot)$('#workspace').innerHTML='<p role="alert">'+esc(e.message)+'</p><button class="p-button secondary" data-admin-retry>Tentar novamente</button>';}}$('#admin-sync').textContent='Atualizado às '+new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});}
async function init(){try{boot=await api('/api/portal/bootstrap');if(!boot.operator){deny();return;}const preferred=localStorage.getItem('helpu-admin-company'),company=boot.companies.find(c=>c.id===preferred)||boot.companies[0];if(!company)throw new Error('Cadastre sua empresa de origem no portal para preparar materiais administrativos.');S=await api('/api/portal/'+company.id+'/state');$('#admin-company').innerHTML=boot.companies.map(c=>`<option value="${esc(c.id)}" ${c.id===company.id?'selected':''}>${esc(c.name)}</option>`).join('');$('#admin-user').textContent=boot.user.name;$('#admin-gate').hidden=true;$('#admin-shell').hidden=false;await render();}catch(e){if(!denied)$('#admin-gate').innerHTML='<h1>Não foi possível abrir a administração.</h1><p>'+esc(e.message)+'</p><a href="admin.html">Tentar novamente</a> · <a href="portal.html?mode=client">Abrir minha empresa</a>';}}
$('#dialog-close').addEventListener('click',closeDialog);$('#admin-refresh').addEventListener('click',render);$('#admin-logout').addEventListener('click',async()=>{try{await api('/api/auth/logout','POST',{});location.replace('entrar.html');}catch(e){toast(e.message,true);}});$('#admin-company').addEventListener('change',async e=>{const selector=e.target;selector.disabled=true;try{const next=await api('/api/portal/'+encodeURIComponent(selector.value)+'/state');S=next;localStorage.setItem('helpu-admin-company',S.company.id);await render();}catch(e){selector.value=S.company.id;toast(e.message,true);}finally{selector.disabled=false;}});document.addEventListener('click',e=>{if(e.target.closest('[data-admin-retry]'))render();});document.addEventListener('input',e=>{if(e.target.id!=='admin-client-search')return;const query=e.target.value.toLocaleLowerCase('pt-BR').trim();let visible=0;for(const card of document.querySelectorAll('[data-client-name]')){card.hidden=!card.dataset.clientName.includes(query);if(!card.hidden)visible++;}$('#admin-client-empty').hidden=visible>0;});window.addEventListener('hashchange',render);init();
